// Package shared embeds the data files shared by the Go binaries and the Python tools
// (make_corpus.py, analyze.py read the same JSON files from this directory).
package shared

import _ "embed"

// WordsJSON is words.json (generated by gen_words.py): output tokens + nonce alphabet.
//
//go:embed words.json
var WordsJSON []byte

// CanariesJSON is canaries.json (generated by gen_canaries.py).
//
//go:embed canaries.json
var CanariesJSON []byte
